/**
 * Synthesize GitHub webhook payloads from data you can *read* about a PR, so
 * `agent-sdk github replay` can exercise a `githubChannel()` without repo
 * admin, without the `gh webhook forward` relay, and deterministically (great
 * for hillclimbing).
 *
 * Payloads are shaped to satisfy the channel's parsers (see `github-channel.ts`);
 * `undefined` fields are dropped by `JSON.stringify` before delivery.
 */
import { createHmac } from "node:crypto";
/** Parse a PR URL or `owner/repo#N`. Returns undefined when neither matches. */
export function parseGitHubPrRef(raw) {
    const text = raw.trim();
    const url = text.match(/https?:\/\/(?:www\.)?github\.com\/([\w.-]+)\/([\w.-]+)\/pull\/(\d+)/i);
    const hash = url ?? text.match(/^([\w.-]+)\/([\w.-]+)#(\d+)$/);
    if (hash === null) {
        return undefined;
    }
    const owner = hash[1];
    const repo = hash[2];
    const number = Number(hash[3]);
    return {
        owner,
        repo,
        number,
        url: `https://github.com/${owner}/${repo}/pull/${number}`,
        label: `${owner}/${repo}#${number}`,
    };
}
/** Webhook events replay knows how to synthesize. */
export const SYNTHESIZABLE_EVENTS = [
    "pull_request",
    "issue_comment",
    "pull_request_review_comment",
    "check_run",
    "check_suite",
    "workflow_run",
    "status",
];
export function isSynthesizableEvent(event) {
    return SYNTHESIZABLE_EVENTS.includes(event);
}
/** Build a webhook payload for `input.event` from the PR data. */
export function synthesizeGitHubEvent(input) {
    const { repo, pull } = input;
    const author = pull.user ?? undefined;
    const actor = input.sender ?? author ?? { login: "agent-serve-replay" };
    const repository = repoPayload(repo);
    const apiPrUrl = `https://api.github.com/repos/${repo.full_name}/pulls/${pull.number}`;
    const prRefs = [{ number: pull.number, url: apiPrUrl, html_url: pull.html_url }];
    switch (input.event) {
        case "pull_request":
            return {
                eventName: "pull_request",
                action: input.action ?? "synchronize",
                payload: {
                    action: input.action ?? "synchronize",
                    number: pull.number,
                    repository,
                    sender: userPayload(actor),
                    pull_request: pullRequestPayload(pull, author),
                },
            };
        case "issue_comment": {
            if (input.comment === undefined || input.comment === "") {
                return { error: "issue_comment needs --comment" };
            }
            const id = commentId(pull.number, 1);
            return {
                eventName: "issue_comment",
                action: "created",
                payload: {
                    action: "created",
                    repository,
                    sender: userPayload(actor),
                    issue: {
                        number: pull.number,
                        html_url: pull.html_url,
                        pull_request: { url: apiPrUrl, html_url: pull.html_url },
                    },
                    comment: {
                        id,
                        body: input.comment,
                        html_url: `${pull.html_url}#issuecomment-${id}`,
                        user: userPayload(actor),
                    },
                },
            };
        }
        case "pull_request_review_comment": {
            if (input.comment === undefined || input.comment === "") {
                return { error: "pull_request_review_comment needs --comment" };
            }
            const id = commentId(pull.number, 2);
            return {
                eventName: "pull_request_review_comment",
                action: "created",
                payload: {
                    action: "created",
                    repository,
                    sender: userPayload(actor),
                    pull_request: { number: pull.number, html_url: pull.html_url },
                    comment: {
                        id,
                        body: input.comment,
                        html_url: `${pull.html_url}#discussion_r${id}`,
                        path: "README.md",
                        line: 1,
                        user: userPayload(actor),
                    },
                },
            };
        }
        case "check_run":
            return {
                eventName: "check_run",
                action: input.action ?? "completed",
                payload: {
                    action: input.action ?? "completed",
                    repository,
                    sender: ciSender(input.check),
                    check_run: {
                        id: input.check?.id ?? commentId(pull.number, 3),
                        name: input.check?.name ?? "ci",
                        head_sha: pull.head.sha,
                        status: "completed",
                        conclusion: input.conclusion ?? input.check?.conclusion ?? "failure",
                        app: ciApp(input.check),
                        check_suite: { id: commentId(pull.number, 4) },
                        pull_requests: prRefs,
                    },
                },
            };
        case "check_suite":
            return {
                eventName: "check_suite",
                action: input.action ?? "completed",
                payload: {
                    action: input.action ?? "completed",
                    repository,
                    sender: ciSender(input.check),
                    check_suite: {
                        id: input.check?.id ?? commentId(pull.number, 4),
                        head_sha: pull.head.sha,
                        status: "completed",
                        conclusion: input.conclusion ?? input.check?.conclusion ?? "failure",
                        app: ciApp(input.check),
                        pull_requests: prRefs,
                    },
                },
            };
        case "workflow_run":
            return {
                eventName: "workflow_run",
                action: input.action ?? "completed",
                payload: {
                    action: input.action ?? "completed",
                    repository,
                    sender: ciSender(input.check),
                    workflow_run: {
                        id: input.check?.id ?? commentId(pull.number, 5),
                        name: input.check?.name ?? "CI",
                        head_sha: pull.head.sha,
                        status: "completed",
                        conclusion: input.conclusion ?? "failure",
                        pull_requests: prRefs,
                    },
                },
            };
        case "status": {
            const state = input.state ?? input.conclusion ?? "failure";
            return {
                eventName: "status",
                payload: {
                    state,
                    sha: pull.head.sha,
                    context: input.context ?? "buildkite/build",
                    description: `Replayed ${state} status`,
                    target_url: null,
                    repository,
                    sender: ciSender(input.check),
                    branches: [{ name: pull.head.ref, commit: { sha: pull.head.sha } }],
                    commit: { sha: pull.head.sha, html_url: pull.html_url },
                    pull_requests: prRefs,
                },
            };
        }
        default:
            return { error: `cannot synthesize unsupported event: ${input.event}` };
    }
}
/** Hex HMAC-SHA256 for the `X-Hub-Signature-256` header (`sha256=<hex>`). */
export function signGitHubWebhookBody(options) {
    return createHmac("sha256", options.secret).update(options.body).digest("hex");
}
/**
 * Resolve the events to replay: explicit list (validated), `*` → the channel's
 * declared events intersected with what replay can synthesize, or the default
 * (`pull_request`).
 */
export function selectReplayEvents(requested, channelEvents) {
    if (requested === undefined || requested.length === 0) {
        return { events: ["pull_request"], unsupported: [] };
    }
    if (requested.length === 1 && requested[0] === "*") {
        const events = channelEvents.filter(isSynthesizableEvent);
        return {
            events: events.length > 0 ? events : ["pull_request"],
            unsupported: [],
        };
    }
    const events = [];
    const unsupported = [];
    for (const event of requested) {
        if (isSynthesizableEvent(event)) {
            events.push(event);
        }
        else {
            unsupported.push(event);
        }
    }
    return { events, unsupported };
}
function repoPayload(repo) {
    const [ownerFromName, nameFromFull] = repo.full_name.split("/");
    return {
        id: repo.id,
        name: repo.name ?? nameFromFull,
        full_name: repo.full_name,
        html_url: repo.html_url,
        default_branch: repo.default_branch,
        owner: { login: repo.owner?.login ?? ownerFromName },
    };
}
function pullRequestPayload(pull, author) {
    return {
        number: pull.number,
        html_url: pull.html_url,
        title: pull.title,
        body: pull.body ?? null,
        draft: pull.draft ?? false,
        merged: pull.merged ?? false,
        user: author === undefined ? undefined : userPayload(author),
        head: {
            ref: pull.head.ref,
            sha: pull.head.sha,
            repo: pull.head.repo,
        },
        base: { ref: pull.base.ref, sha: pull.base.sha },
    };
}
function userPayload(user) {
    return { login: user.login, id: user.id, type: user.type ?? "User" };
}
function ciSender(check) {
    const slug = check?.app?.slug;
    const login = slug === undefined ? "github-actions[bot]" : `${slug}[bot]`;
    return { login, type: "Bot" };
}
function ciApp(check) {
    return {
        slug: check?.app?.slug ?? "github-actions",
        name: check?.app?.name ?? "GitHub Actions",
    };
}
/** Stable, PR-scoped synthetic id so re-runs are reproducible. */
function commentId(prNumber, kind) {
    return prNumber * 100 + kind;
}
